window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b9bdabd16e278cf5"]={"versions": [{"id": "FIG-b9bdabd16e278cf5", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-Diagramm) zur Spezifikation des Sendemodus-Umschalverhaltens (Transmission Mode Selection, TMS) im AUTOSAR Classic Platform Communication Stack (<code>AUTOSAR_SWS_COM</code>). Das Diagramm illustriert das zeitliche Zusammenspiel periodischer I-PDU-Übertragungen (<code>Periodic + Periodic</code>) beim Wechsel zwischen zwei Übertragungsmodi mit unterschiedlichen Zykluszeiten unter Berücksichtigung von Mindestsendeabstand und Reaktionszeit.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zeitachse <code>t</code>:</strong> Horizontale Zeitbasis für Sende- und Triggerereignisse.\n</li><li><strong>I-PDU-Sendeimpulse (grüne Pfeile nach unten):</strong> Tatsächlich an die unteren Schichten (PDU Router / Interface) abgesetzte periodische Sendeanforderungen.\n</li><li><strong>Signaländerung / TMS-Ereignis (orangefarbener Blitz mit Signalwerten <code>v = a</code>, <code>v = b</code>):</strong> Eintreffen eines Signalwerts, der eine Neubewertung des Transmission Mode auslöst (Umschaltung von Modus A nach B bzw. B nach A).\n</li><li><strong>Verzögerter/unterdrückter Sendeimpuls (blauer, gestrichelter Pfeil nach unten):</strong> Geplanter Sendezeitpunkt, der aufgrund des Mindestsendeabstands nicht unmittelbar ausgeführt werden darf.\n</li><li><strong>Timing-Parameter:</strong>\n<ul class=\"fig-list\"><li><code>tc1</code>: Periodische Zykluszeit im Transmission Mode A.\n</li><li><code>tc2</code>: Periodische Zykluszeit im Transmission Mode B (mit <code>tc2 &lt; tc1</code>).\n</li><li><code>dt</code>: Mindestsendeabstand (Minimum Delay Time, MDT).\n</li><li><code>tr, min</code>: Minimale Reaktionszeit des COM-Moduls nach Eintreffen des Umschaltereignisses bis zum ersten Sendeimpuls des neuen Modus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Modus A (<code>v = a</code>):</strong> Die I-PDU wird periodisch mit der Zykluszeit <code>tc1</code> übertragen.\n</li><li><strong>Umschaltung zu Modus B (<code>v = b</code>):</strong> Ein Signalwertwechsel löst den Moduswechsel aus. Der Mindestsendeabstand <code>dt</code> nach dem letzten regulären Sendeimpuls ist bereits abgelaufen. Nach Ablauf der minimalen Reaktionszeit <code>tr, min</code> wird der erste Sendeimpuls des neuen Modus unverzüglich abgesetzt.\n</li><li><strong>Modus B (<code>v = b</code>):</strong> Die I-PDU wird nachfolgend periodisch mit der kürzeren Zykluszeit <code>tc2</code> übertragen.\n</li><li><strong>Rückschaltung zu Modus A (<code>v = a</code>):</strong> Der Signalwertwechsel erfolgt kurz nach einem Sendeimpuls von Modus B. Zu diesem Zeitpunkt ist der Mindestsendeabstand <code>dt</code> noch aktiv. Der reguläre Sendeanstoß nach Ablauf von <code>tr, min</code> (blauer gestrichelter Pfeil) wird blockiert.\n</li><li><strong>Verzögerter Neustart:</strong> Der erste Sendeimpuls des Modus A wird exakt bis zum Ablauf des Mindestsendeabstands <code>dt</code> verzögert und erst danach abgesetzt. Daran schließt sich die reguläre Periodizität mit <code>tc1</code> an.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm konkretisiert die normativen Anforderungen des AUTOSAR COM bezüglich der Einhaltung der <code>ComMinimumDelayTime</code> bei Moduswechseln:</p>\n<ul class=\"fig-list\"><li>Ein Transmission-Mode-Wechsel darf niemals den konfigurierten Mindestsendeabstand (<code>dt</code> / MDT) verletzen.\n</li><li>Falls die minimale Reaktionszeit <code>tr, min</code> nach einer TMS-Umschaltung innerhalb des aktiven MDT-Fensters abläuft, muss der Sendeanstoß verzögert werden, bis der Mindestsendeabstand vollständig verstrichen ist.\n</li><li>Ist der Mindestsendeabstand bereits abgelaufen, erfolgt die Aussendung nach <code>tr, min</code>.\n</li></ul>"}, {"id": "FIG-116507302c6e0c47", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-Diagramm) zur Spezifikation des Sendemodus-Umschalverhaltens (Transmission Mode Selection, TMS) im AUTOSAR Classic Platform Communication Stack (<code>AUTOSAR_SWS_COM</code>). Das Diagramm illustriert das zeitliche Zusammenspiel periodischer I-PDU-Übertragungen (<code>Periodic + Periodic</code>) beim Wechsel zwischen zwei Übertragungsmodi mit unterschiedlichen Zykluszeiten unter Berücksichtigung von Mindestsendeabstand und Reaktionszeit.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zeitachse <code>t</code>:</strong> Horizontale Zeitbasis für Sende- und Triggerereignisse.\n</li><li><strong>I-PDU-Sendeimpulse (grüne Pfeile nach unten):</strong> Tatsächlich an die unteren Schichten (PDU Router / Interface) abgesetzte periodische Sendeanforderungen.\n</li><li><strong>Signaländerung / TMS-Ereignis (orangefarbener Blitz mit Signalwerten <code>v = a</code>, <code>v = b</code>):</strong> Eintreffen eines Signalwerts, der eine Neubewertung des Transmission Mode auslöst (Umschaltung von Modus A nach B bzw. B nach A).\n</li><li><strong>Verzögerter/unterdrückter Sendeimpuls (blauer, gestrichelter Pfeil nach unten):</strong> Geplanter Sendezeitpunkt, der aufgrund des Mindestsendeabstands nicht unmittelbar ausgeführt werden darf.\n</li><li><strong>Timing-Parameter:</strong>\n<ul class=\"fig-list\"><li><code>tc1</code>: Periodische Zykluszeit im Transmission Mode A.\n</li><li><code>tc2</code>: Periodische Zykluszeit im Transmission Mode B (mit <code>tc2 &lt; tc1</code>).\n</li><li><code>dt</code>: Mindestsendeabstand (Minimum Delay Time, MDT).\n</li><li><code>tr, min</code>: Minimale Reaktionszeit des COM-Moduls nach Eintreffen des Umschaltereignisses bis zum ersten Sendeimpuls des neuen Modus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Modus A (<code>v = a</code>):</strong> Die I-PDU wird periodisch mit der Zykluszeit <code>tc1</code> übertragen.\n</li><li><strong>Umschaltung zu Modus B (<code>v = b</code>):</strong> Ein Signalwertwechsel löst den Moduswechsel aus. Der Mindestsendeabstand <code>dt</code> nach dem letzten regulären Sendeimpuls ist bereits abgelaufen. Nach Ablauf der minimalen Reaktionszeit <code>tr, min</code> wird der erste Sendeimpuls des neuen Modus unverzüglich abgesetzt.\n</li><li><strong>Modus B (<code>v = b</code>):</strong> Die I-PDU wird nachfolgend periodisch mit der kürzeren Zykluszeit <code>tc2</code> übertragen.\n</li><li><strong>Rückschaltung zu Modus A (<code>v = a</code>):</strong> Der Signalwertwechsel erfolgt kurz nach einem Sendeimpuls von Modus B. Zu diesem Zeitpunkt ist der Mindestsendeabstand <code>dt</code> noch aktiv. Der reguläre Sendeanstoß nach Ablauf von <code>tr, min</code> (blauer gestrichelter Pfeil) wird blockiert.\n</li><li><strong>Verzögerter Neustart:</strong> Der erste Sendeimpuls des Modus A wird exakt bis zum Ablauf des Mindestsendeabstands <code>dt</code> verzögert und erst danach abgesetzt. Daran schließt sich die reguläre Periodizität mit <code>tc1</code> an.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm konkretisiert die normativen Anforderungen des AUTOSAR COM bezüglich der Einhaltung der <code>ComMinimumDelayTime</code> bei Moduswechseln:</p>\n<ul class=\"fig-list\"><li>Ein Transmission-Mode-Wechsel darf niemals den konfigurierten Mindestsendeabstand (<code>dt</code> / MDT) verletzen.\n</li><li>Falls die minimale Reaktionszeit <code>tr, min</code> nach einer TMS-Umschaltung innerhalb des aktiven MDT-Fensters abläuft, muss der Sendeanstoß verzögert werden, bis der Mindestsendeabstand vollständig verstrichen ist.\n</li><li>Ist der Mindestsendeabstand bereits abgelaufen, erfolgt die Aussendung nach <code>tr, min</code>.\n</li></ul>"}, {"id": "FIG-dd10b60eb89a619d", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-Diagramm) zur Spezifikation des Sendemodus-Umschalverhaltens (Transmission Mode Selection, TMS) im AUTOSAR Classic Platform Communication Stack (<code>AUTOSAR_SWS_COM</code>). Das Diagramm illustriert das zeitliche Zusammenspiel periodischer I-PDU-Übertragungen (<code>Periodic + Periodic</code>) beim Wechsel zwischen zwei Übertragungsmodi mit unterschiedlichen Zykluszeiten unter Berücksichtigung von Mindestsendeabstand und Reaktionszeit.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zeitachse <code>t</code>:</strong> Horizontale Zeitbasis für Sende- und Triggerereignisse.\n</li><li><strong>I-PDU-Sendeimpulse (grüne Pfeile nach unten):</strong> Tatsächlich an die unteren Schichten (PDU Router / Interface) abgesetzte periodische Sendeanforderungen.\n</li><li><strong>Signaländerung / TMS-Ereignis (orangefarbener Blitz mit Signalwerten <code>v = a</code>, <code>v = b</code>):</strong> Eintreffen eines Signalwerts, der eine Neubewertung des Transmission Mode auslöst (Umschaltung von Modus A nach B bzw. B nach A).\n</li><li><strong>Verzögerter/unterdrückter Sendeimpuls (blauer, gestrichelter Pfeil nach unten):</strong> Geplanter Sendezeitpunkt, der aufgrund des Mindestsendeabstands nicht unmittelbar ausgeführt werden darf.\n</li><li><strong>Timing-Parameter:</strong>\n<ul class=\"fig-list\"><li><code>tc1</code>: Periodische Zykluszeit im Transmission Mode A.\n</li><li><code>tc2</code>: Periodische Zykluszeit im Transmission Mode B (mit <code>tc2 &lt; tc1</code>).\n</li><li><code>dt</code>: Mindestsendeabstand (Minimum Delay Time, MDT).\n</li><li><code>tr, min</code>: Minimale Reaktionszeit des COM-Moduls nach Eintreffen des Umschaltereignisses bis zum ersten Sendeimpuls des neuen Modus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Modus A (<code>v = a</code>):</strong> Die I-PDU wird periodisch mit der Zykluszeit <code>tc1</code> übertragen.\n</li><li><strong>Umschaltung zu Modus B (<code>v = b</code>):</strong> Ein Signalwertwechsel löst den Moduswechsel aus. Der Mindestsendeabstand <code>dt</code> nach dem letzten regulären Sendeimpuls ist bereits abgelaufen. Nach Ablauf der minimalen Reaktionszeit <code>tr, min</code> wird der erste Sendeimpuls des neuen Modus unverzüglich abgesetzt.\n</li><li><strong>Modus B (<code>v = b</code>):</strong> Die I-PDU wird nachfolgend periodisch mit der kürzeren Zykluszeit <code>tc2</code> übertragen.\n</li><li><strong>Rückschaltung zu Modus A (<code>v = a</code>):</strong> Der Signalwertwechsel erfolgt kurz nach einem Sendeimpuls von Modus B. Zu diesem Zeitpunkt ist der Mindestsendeabstand <code>dt</code> noch aktiv. Der reguläre Sendeanstoß nach Ablauf von <code>tr, min</code> (blauer gestrichelter Pfeil) wird blockiert.\n</li><li><strong>Verzögerter Neustart:</strong> Der erste Sendeimpuls des Modus A wird exakt bis zum Ablauf des Mindestsendeabstands <code>dt</code> verzögert und erst danach abgesetzt. Daran schließt sich die reguläre Periodizität mit <code>tc1</code> an.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm konkretisiert die normativen Anforderungen des AUTOSAR COM bezüglich der Einhaltung der <code>ComMinimumDelayTime</code> bei Moduswechseln:</p>\n<ul class=\"fig-list\"><li>Ein Transmission-Mode-Wechsel darf niemals den konfigurierten Mindestsendeabstand (<code>dt</code> / MDT) verletzen.\n</li><li>Falls die minimale Reaktionszeit <code>tr, min</code> nach einer TMS-Umschaltung innerhalb des aktiven MDT-Fensters abläuft, muss der Sendeanstoß verzögert werden, bis der Mindestsendeabstand vollständig verstrichen ist.\n</li><li>Ist der Mindestsendeabstand bereits abgelaufen, erfolgt die Aussendung nach <code>tr, min</code>.\n</li></ul>"}, {"id": "FIG-0a8f656de2757de9", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing-Diagramm) zur Spezifikation des Sendemodus-Umschaltverhaltens (Transmission Mode Selection, TMS) im AUTOSAR Classic Platform Communication Stack (<code>AUTOSAR_SWS_COM</code>). Das Diagramm illustriert das zeitliche Zusammenspiel periodischer I-PDU-Übertragungen (<code>Periodic + Periodic</code>) beim Wechsel zwischen zwei Übertragungsmodi mit unterschiedlichen Zykluszeiten unter Berücksichtigung von Mindestsendeabstand und Reaktionszeit.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zeitachse <code>t</code>:</strong> Horizontale Zeitbasis für Sende- und Triggerereignisse.\n</li><li><strong>I-PDU-Sendeimpulse (grüne Pfeile nach unten):</strong> Tatsächlich an die unteren Schichten (PDU Router / Interface) abgesetzte periodische Sendeanforderungen.\n</li><li><strong>Signaländerung / TMS-Ereignis (rote Dreiecksmarkierungen mit Signalwerten <code>v=a</code>, <code>v=b</code>):</strong> Übergabe eines Signalwerts an COM, der eine Umschaltung des Transmission Mode bewirkt.\n</li><li><strong>Verzögerter/geblockter Sendeimpuls (blauer, gestrichelter Pfeil nach unten):</strong> Theoretischer Sendezeitpunkt nach Ablauf der internen Reaktionszeit, der wegen aktiven Mindestsendeabstands nicht gesendet werden darf.\n</li><li><strong>Timing-Parameter:</strong>\n<ul class=\"fig-list\"><li><code>tc1</code>: Periodische Zykluszeit im Transmission Mode A.\n</li><li><code>tc2</code>: Periodische Zykluszeit im Transmission Mode B (mit <code>tc2 &lt; tc1</code>).\n</li><li><code>d</code>: Mindestsendeabstand (Minimum Delay Time, MDT).\n</li><li><code>tr</code>: Reaktionszeit des COM-Moduls nach Eintreffen des Umschaltereignisses bis zur Sendeanforderung.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Modus A (<code>v=a</code>):</strong> Periodische Übertragung der I-PDU im Zyklus <code>tc1</code>.\n</li><li><strong>Umschaltung zu Modus B (<code>v=b</code>):</strong> Signalübergabe triggert die TMS-Umschaltung. Da der Mindestsendeabstand <code>d</code> zum vorherigen Sendeimpuls bereits verstrichen ist, wird nach Ablauf der Reaktionszeit <code>tr</code> unmittelbar der erste Sendeimpuls des neuen Modus initiiert.\n</li><li><strong>Modus B (<code>v=b</code>):</strong> Fortführung der periodischen Übertragung mit dem kürzeren Zyklus <code>tc2</code>.\n</li><li><strong>Rückschaltung zu Modus A (<code>v=a</code>):</strong> Signalübergabe erfolgt kurz nach einem Modus-B-Sendeimpuls. Die Reaktionszeit <code>tr</code> läuft ab, während der Mindestsendeabstand <code>d</code> noch aktiv ist; der Sendeanstoß (blauer gestrichelter Pfeil) wird geblockt.\n</li><li><strong>Verzögerter Neustart:</strong> Erst mit Ablauf des Mindestsendeabstands <code>d</code> wird der erste Sendeimpuls für Modus A freigegeben. Anschließend setzt sich die periodische Übertragung mit Zykluszeit <code>tc1</code> fort.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm konkretisiert die normativen Anforderungen des AUTOSAR COM bezüglich der Einhaltung der <code>ComMinimumDelayTime</code> bei Moduswechseln:</p>\n<ul class=\"fig-list\"><li>Ein Transmission-Mode-Wechsel darf niemals den konfigurierten Mindestsendeabstand (<code>dt</code> / MDT) verletzen.\n</li><li>Falls die minimale Reaktionszeit <code>tr, min</code> nach einer TMS-Umschaltung innerhalb des aktiven MDT-Fensters abläuft, muss der Sendeanstoß verzögert werden, bis der Mindestsendeabstand vollständig verstrichen ist.\n</li><li>Ist der Mindestsendeabstand bereits abgelaufen, erfolgt die Aussendung nach <code>tr, min</code>.\n</li></ul>"}], "trans": [{"from": "FIG-b9bdabd16e278cf5", "to": "FIG-116507302c6e0c47", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-116507302c6e0c47", "to": "FIG-dd10b60eb89a619d", "fr": "R3.2.3", "tr": "R4.0.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-dd10b60eb89a619d", "to": "FIG-0a8f656de2757de9", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Darstellung der Signal-Schreibereignisse (TMS-Umschaltung):</strong> Ersetzung der gezackten Blitz-Pfeile durch nach unten zeigende rote Dreieck-Konturen.\n</li><li><strong>Beschriftung der Reaktionszeit:</strong> Umbenennung des Parameters von <code>$t_{r,\\min}$</code> zu <code>$t_r$</code> und Darstellung mittels geschweifter Klammern statt Maßpfeilen.\n</li><li><strong>Darstellung des Mindestsendeabstands:</strong> Kürzung der Beschriftung von <code>dt</code> zu <code>d</code> unterhalb der Zeitachse sowie Markierung mittels geschweifter Klammer.\n</li><li><strong>Abtastung/Rasterung:</strong> Zusätzliche grüne Sendeimpulse im rechten Zeitabschnitt zur Verdeutlichung der Fortsetzung der periodischen Aussendung mit <code>$t_{c1}$</code>.\n</li><li><strong>Typografie und Layout:</strong> Aktualisierung der Schriftart und Linienstärken im Zuge der Angleichung an das AUTOSAR-R4-Grafikschema.\n</li></ul>"}]};
